import fs from 'node:fs';
import path from 'node:path';

const out = path.resolve('/home/ubuntu/alamyasas-web/html-site');
fs.rmSync(out, { recursive: true, force: true });
fs.mkdirSync(out, { recursive: true });
fs.mkdirSync(path.join(out, 'assets'), { recursive: true });
const assetSource = '/home/ubuntu/webdev-static-assets/movion-original';
for (const [from, to] of [['delivery-team-checking-manifest.webp','delivery-team-checking-manifest.webp'],['movers-unloading-boxes.webp','movers-unloading-boxes.webp'],['young-company-workers.webp','young-company-workers.webp'],['parcel-packing-worker.webp','parcel-packing-worker.webp'],['alalami-logo.png','alalami-logo.png'],['Team-1.webp','Team-1.webp'],['Team-2.webp','Team-2.webp'],['Team-3.webp','Team-3.webp'],['Team-4.webp','Team-4.webp'],['Team-5.webp','Team-5.webp']]) fs.copyFileSync(path.join(assetSource, from), path.join(out, 'assets', to));

