const arrow = '<span class="circle-arrow">←</span>';
const icon = (name) => `<span class="icon-box" aria-hidden="true">${name}</span>`;

function areaLinks(group) { return group.map(a => `<a href="${a.slug}.html"><span>نقل أثاث ${a.name}</span><small>${a.gov}</small></a>`).join(''); }
function header(active = '') {
  const links = [['Home','index.html','الرئيسية'],['About','about.html','من نحن'],['Services','services.html','خدماتنا']];
  return `<header class="site-header"><a class="brand" href="index.html"><img src="${LOGO}" alt="العالمي للنقل"></a><nav class="desktop-nav">${links.map(([l,h,t]) => `<a class="${active===l?'active':''}" href="${h}">${t}</a>`).join('')}<div class="nav-dropdown"><button class="${['Team','Pricing','Faq','Blog'].includes(active)?'active':''}" type="button">المزيد <span>⌄</span></button><div class="dropdown-menu"><a href="team.html">فريقنا</a><a href="pricing.html">الأسعار</a><a href="faq.html">الأسئلة الشائعة</a><a href="blog.html">المدونة</a></div></div><div class="areas-dropdown"><button type="button">مناطق الخدمة <span>⌄</span></button><div class="areas-menu"><div><strong>القاهرة</strong>${areaLinks(locationAreas.filter(a=>a.gov==='القاهرة'))}</div><div><strong>الجيزة</strong>${areaLinks(locationAreas.filter(a=>a.gov==='الجيزة'))}</div><a class="areas-all" href="areas.html">عرض كل مناطق القاهرة والجيزة ←</a></div></div><a class="${active==='Contact'?'active':''}" href="contact.html">تواصل معنا</a></nav><a class="pill pill-red header-cta" href="contact.html">اطلب خدمتك ${arrow}</a><button class="menu-button" type="button" aria-label="فتح القائمة">☰</button><nav class="mobile-nav"><a href="index.html">الرئيسية</a><a href="about.html">من نحن</a><a href="services.html">خدماتنا</a><details class="mobile-areas"><summary>مناطق الخدمة</summary><div><strong>القاهرة</strong>${areaLinks(locationAreas.filter(a=>a.gov==='القاهرة'))}</div><div><strong>الجيزة</strong>${areaLinks(locationAreas.filter(a=>a.gov==='الجيزة'))}</div></details><a href="team.html">فريقنا</a><a href="pricing.html">الأسعار</a><a href="faq.html">الأسئلة الشائعة</a><a href="blog.html">المدونة</a><a href="contact.html">تواصل معنا</a><a class="pill pill-red" href="contact.html">اطلب خدمتك ${arrow}</a></nav></header>`;
}
function footer() {
  return `<footer class="footer"><div class="newsletter"><div><div class="eyebrow light">ابقَ على اطلاع</div><h2>نصائح للانتقال<br>وآخر التحديثات</h2></div><form class="newsletter-form"><input type="email" placeholder="أدخل بريدك الإلكتروني" aria-label="البريد الإلكتروني" required><button class="pill pill-red" type="submit">اشترك ${arrow}</button></form></div><div class="footer-main"><div class="footer-brand"><img class="footer-logo" src="${WHITE_LOGO}" alt="العالمي للنقل"><p>نرافقك في كل خطوة لنمنحك تجربة انتقال منظمة وآمنة ومريحة.</p><div class="socials"><a href="#" aria-label="فيسبوك">f</a><a href="#" aria-label="إكس">𝕏</a><a href="#" aria-label="لينكدإن">in</a><a href="#" aria-label="إنستغرام">◎</a></div></div><div><h4>روابط سريعة</h4><a href="index.html">الرئيسية</a><a href="about.html">من نحن</a><a href="services.html">خدماتنا</a><a href="team.html">فريقنا</a></div><div><h4>الدعم</h4><a href="faq.html">مركز المساعدة</a><a href="contact.html">تواصل معنا</a><a href="blog.html">المدونة</a><a href="faq.html">الأسئلة الشائعة</a></div><div><h4>تواصل معنا</h4><a href="contact.html">اطلب عرض سعر عبر النموذج</a><a href="mailto:info@alamytrans.com">info@alamytrans.com</a><span>القاهرة والجيزة، مصر</span><span>الأحد – الخميس: 08:00 – 18:00</span></div></div><div class="footer-bottom"><span>2026 حقوق النشر © العالمي للنقل</span><span><a href="#">سياسة الخصوصية</a><a href="#">الشروط والأحكام</a></span></div></footer>`;
}

function banner(title) { return `<section class="page-banner page-banner-image" style="background-image:linear-gradient(#1118,#1118),url('${SERVICE}')"><div><h1>${title}</h1><p><a href="index.html">الرئيسية</a><span>«</span>${title}</p></div></section>`; }
function card(title, text, image, symbol) { return `<article class="service-card reveal-child"><div>${icon(symbol)}</div><h3>${title}</h3><p>${text}</p><div class="card-image" style="background-image:url('${image}')"></div><a class="card-arrow" href="contact.html" aria-label="تواصل معنا">←</a></article>`; }
function shell(title, active, body, meta = {}) {
  const description = meta.description || 'العالمي لنقل الأثاث تقدم خدمات نقل وتغليف احترافية في القاهرة والجيزة.';
  const canonical = meta.canonical || SITE_URL;
  const image = meta.image || `${SITE_URL}/${HERO}`;
  const schema = meta.schema ? `<script type="application/ld+json">${JSON.stringify(meta.schema)}</script>` : '';
  return `<!doctype html><html lang="ar" dir="rtl"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#123b63"><meta name="description" content="${description}"><meta name="robots" content="index,follow,max-image-preview:large,max-snippet:-1,max-video-preview:-1"><title>${title} — العالمي للنقل</title><link rel="canonical" href="${canonical}"><meta property="og:locale" content="ar_EG"><meta property="og:type" content="website"><meta property="og:site_name" content="العالمي لنقل الأثاث"><meta property="og:title" content="${title} — العالمي"><meta property="og:description" content="${description}"><meta property="og:url" content="${canonical}"><meta property="og:image" content="${image}"><meta property="og:image:alt" content="العالمي لنقل الأثاث"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="${title} — العالمي"><meta name="twitter:description" content="${description}"><meta name="twitter:image" content="${image}"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=IBM+Plex+Sans+Arabic:wght@400;500;600;700&display=swap" rel="stylesheet"><link rel="icon" type="image/png" href="${LOGO}"><link rel="stylesheet" href="styles.css">${schema}</head><body>${header(active)}${body}${footer()}<script src="script.js" defer></script></body></html>`;
}

