fs.writeFileSync(path.join(out, 'script.js'), `document.addEventListener('DOMContentLoaded',()=>{const header=document.querySelector('.site-header'),menu=document.querySelector('.menu-button'),mobile=document.querySelector('.mobile-nav');if(menu){menu.addEventListener('click',()=>{mobile.classList.toggle('is-open');menu.textContent=mobile.classList.contains('is-open')?'×':'☰';});}const revealItems=document.querySelectorAll('.reveal');if('IntersectionObserver' in window){const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('is-visible');io.unobserve(e.target);}}),{threshold:.12});revealItems.forEach(e=>io.observe(e));}else{revealItems.forEach(e=>e.classList.add('is-visible'));}document.querySelectorAll('.faq-item button').forEach(b=>b.addEventListener('click',()=>{const item=b.closest('.faq-item');document.querySelectorAll('.faq-item').forEach(x=>{if(x!==item)x.classList.remove('open');});item.classList.toggle('open');b.querySelector('b').textContent=item.classList.contains('open')?'×':'+';}));document.querySelectorAll('form').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();const status=form.querySelector('.form-status');if(status){status.textContent='شكرًا لك. سيتواصل معك فريقنا قريبًا.';}else{const s=document.createElement('p');s.className='form-status';s.textContent='تم الاشتراك بنجاح.';form.appendChild(s);}}));});`);
fs.appendFileSync(path.join(out, 'styles.css'), `\n/* Al Alamy logo alignment — preserve the full square mark with generous desktop presence. */\n.site-header{height:100px}.site-header .brand{width:96px;flex:0 0 96px}.site-header .brand img{width:96px;height:96px}.footer-logo{width:128px;height:128px}@media (max-width:900px){.site-header{height:84px}.site-header .brand{width:78px;flex-basis:78px}.site-header .brand img{width:78px;height:78px}.mobile-nav{top:84px;max-height:calc(100vh - 84px)}}@media (max-width:600px){.site-header{height:76px}.site-header .brand{width:66px;flex-basis:66px}.site-header .brand img{width:66px;height:66px}.mobile-nav{top:76px;max-height:calc(100vh - 76px)}.footer-logo{width:112px;height:112px}}\n`);
